// INHA WORLD · Equipment model loader (Local Equipment Projection P0, Equipment Asset Binding P0).
// Binds a catalog `modelAssetId` to a loadable model: itemId → catalog modelAssetId → this registry →
// same-origin URL. Items whose modelAssetId is null never reach the loader. The GLBs are generated by
// assets/build_equipment.py and authored in their anchor's space, so no per-item transform exists.
// Renderer-agnostic: uses the PlayCanvas asset registry only (works on WebGPU and WebGL2 devices).
// PlayCanvas reuses a loaded container per URL, so re-equipping instantiates a new entity from the
// already-downloaded asset instead of fetching it again.

/** modelAssetId → same-origin model URL (Asset Binding P0: HEAD cap, BACK backpack · Expansion P1a: TOP hoodie). */
export const EQUIPMENT_MODEL_REGISTRY = Object.freeze({
  "equipment.head.induck_cap.v1": "/assets/induck-cap-v1.glb",
  "equipment.back.induck_backpack.v1": "/assets/induck-backpack-v1.glb",
  "equipment.top.induck_hoodie.v1": "/assets/induck-hoodie-v1.glb",
  // MCM 2026 survivor top has its own stable asset id and dedicated event model.
  // Reward/equip contracts stay stable while the visual remains independently replaceable.
  "equipment.top.mcm_2026_survivor.v1": "/assets/mcm-survivor-top-v1.gltf"
});

/**
 * @param {{ app: object, registry?: Record<string, string> }} options
 * @returns {(modelAssetId: string) => Promise<object>} resolves to a render entity (not yet parented)
 */
export function createEquipmentModelLoader({ app, registry = EQUIPMENT_MODEL_REGISTRY } = {}) {
  return function loadEquipmentModel(modelAssetId) {
    const url = Object.prototype.hasOwnProperty.call(registry, modelAssetId) ? registry[modelAssetId] : null;
    if (typeof url !== "string" || !url) return Promise.reject(new Error("UNREGISTERED_MODEL_ASSET"));
    return new Promise((resolve, reject) => {
      app.assets.loadFromUrl(url, "container", (error, asset) => {
        if (error || !asset?.resource) { reject(error || new Error("MODEL_ASSET_UNAVAILABLE")); return; }
        try {
          const entity = asset.resource.instantiateRenderEntity({ castShadows: true, receiveShadows: true });
          entity.name = `Equipment_Model_${modelAssetId}`;
          resolve(entity);
        } catch (cause) {
          reject(cause);
        }
      });
    });
  };
}
